WITH enriched AS (SELECT id, session_id, event_type, page, event_time, duration_sec, DENSE_RANK() OVER w_grp AS duration_sec_dense_rank, ROW_NUMBER() OVER (PARTITION BY event_type ORDER BY duration_sec DESC, id) AS row_seq, NTILE(5) OVER (PARTITION BY session_id ORDER BY duration_sec, id) AS duration_sec_bucket FROM web_events WINDOW w_grp AS (PARTITION BY event_type ORDER BY duration_sec)) SELECT id, event_type, page, event_time, row_seq, duration_sec_bucket, CASE WHEN event_type RLIKE '^(purchase|page_view)$' THEN 'GROUP_A' WHEN event_type RLIKE '^(click|add_to_cart)$' THEN 'PRIORITY' ELSE 'GROUP_B' END AS event_type_zone FROM enriched;
